        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          redate.reset();
          setDate(e.target.value);
        }}
      />{' '}
      <button
        type="button"
        data-testid="bulk-redate"
        disabled={redate.isPending}
